private double calculateWeight(Integer value1, Integer value2) {
    // Calculate the weight based on the formula given in the problem
    double weight = 1 - (1 - value1) * (1 - value2);

    // Normalize the weight
    weight = weight / (1 - weight) - 1;

    // Return the weight
