    // Convert the event to a string using the appropriate converter
    String eventString = converters.stream()
                                .filter(converter -> converter.isSupported(event.getStackTraceElement().getClassName()))
                                .map(converter -> converter.convert(event))
                                .findFirst()
                                .orElse("");

