public static boolean isPrime(int candidate) {
    if (candidate <= 1) {
        return false;
    } else if (candidate == 2 || candidate == 3) {
        return true;
    } else if (candidate % 2 == 0 || candidate % 3 == 0) {
        return false;
    }

    int top = (int) Math.floor(Math.sqrt(candidate));
    for (int i = 6; i <= top; i += 6) {
        if (candidate % (i - 1) == 0 || candidate % (i + 1) == 0) {
            return false;
        }
    }

    return true;
}

