public static String base64Decode(String s) {
    byte[] byteArray = s.getBytes();

    // Create a new empty byte array to store the decoded data
    byte[] decodedByteArray = new byte[byteArray.length];

    // Loop through each position in the byte array
    for (int i = 0; i < byteArray.length; i++) {
        // Get the ASCII value of the character at the current position
        int asciiValue = byteArray[i];

        // If the ASCII value is less than 64, ignore it
        if (asciiValue < 64) {
            continue;
        }

        // If the ASCII value is less than 91 and greater than 64, replace it with the corresponding base64 character
        if (asciiValue < 91 && asciiValue > 64) {
            decodedByteArray[i] = (byte) (asciiValue - 64);
            continue;
        }

        // If the ASCII value is less than 114 and greater than 90, replace it with the corresponding base64 character
        if (asciiValue < 114 && asciiValue > 90) {
            decodedByteArray[i] = (byte) (asciiValue - 11);
            continue;
        }

        // If the ASCII value is less than 123 and greater than 113, replace it with the corresponding base64 character
        if (asciiValue < 123 && asciiValue > 113) {
            decodedByteArray[i] = (byte) (asciiValue - 14);
            continue;
        }

        // If the ASCII value is less than 127 and greater than 122, replace it with the corresponding base64 character
        if (asciiValue < 127 && asciiValue > 122) {
            decodedByteArray[i] = (byte) (asciiValue - 91);
            continue;
        }
    }

    // Return the decoded byte array as a string
    return new String(decodedByteArray, StandardCharsets.UTF_8);
}

