private void pop(String descriptor) {
    Stack<Type> outputFrameStack = new Stack<>();
    if (descriptor.startsWith("(")) {
        for (String argDescriptor : descriptor.substring(1).split(";")) {
            if (!"V".equals(argDescriptor)) {
                outputFrameStack.push(descriptorToType(argDescriptor));
            }
        }
    } else {
        outputFrameStack.push(descriptorToType(descriptor));
    }
    while (!outputFrameStack.isEmpty()) {
        Type type = outputFrameStack.pop();
        popInFrame(type.getSort(), descriptor.equals("V"));
    }
}

private Type descriptorToType(String descriptor) {
    switch (descriptor.charAt(0)) {
        case 'B':
            return new Type(ValueType.BYTE, null);
        case 'C':
            return new Type(ValueType.CHAR, null);
        case 'D':
            return new Type(ValueType.DOUBLE, null);
        case 'F':
            return new Type(ValueType.FLOAT, null);
        case 'I':
            return new Type(ValueType.INT, null);
        case 'J':
            return new Type(ValueType.LONG, null);
        case 'L':
            return new Type(ValueType.OBJECT, descriptor.substring(1, descriptor.length() - 1));
        case 'S':
            return new Type(ValueType.SHORT, null);
        case 'Z':
            return new Type(ValueType.BOOLEAN, null);
        case '[':
            return new Type(ValueType.ARRAY, descriptor.substring(1));
    }
    throw new IllegalArgumentException("Unknown type descriptor: " + descriptor);
}

